totalPages: function() {
  if (this.get("user_count") == 0) { return 0; }
  return Math.ceil(this.get("user_count") / this.get("limit"));
}.property("limit", "user_count"),

setupController: function(controller, model) {
  this.controllerFor('group').set('showing', 'members');
  controller.set("model", model);
  model.setProperties({ offset: 0, limit: 50 });
  return model.findMembers().then(function() {
    if (model.get("user_count") > model.get("members").length) {
      model.set("limit", model.get("user_count"));
      return model.findMembers();
    }
  });
}
